<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api } from '../../api/client'
import { duration, stateLabels, tone } from '../reports/presentation'
const router = useRouter(), items = ref([]), error = ref(''), loading = ref(true), activeTab = ref('pending'), opening = ref(null)
const pending = computed(() => items.value.filter(i => i.state !== 'submitted'))
const completed = computed(() => items.value.filter(i => i.state === 'submitted'))
const visible = computed(() => activeTab.value === 'pending' ? pending.value : completed.value)
async function open(item) { if (opening.value) return; opening.value = item.invitation_id; error.value = ''; try { const id = item.session_id || (await api(`/invitations/${item.invitation_id}/accept`, { method: 'POST' })).session_id; router.push(`/sessions/${id}`) } catch (e) { error.value = e.message } finally { opening.value = null } }
onMounted(async () => { try { items.value = await api('/me/assessments') } catch (e) { error.value = e.message } finally { loading.value = false } })
</script>
<template><main class="page"><div class="page-heading"><div><h1>나의 평가</h1><p class="muted">초대받은 평가를 확인하고, 준비가 되면 시작하세요.</p></div></div><p v-if="error" class="error" role="alert">{{ error }}</p><div class="filter-tabs"><button :class="{ active: activeTab === 'pending' }" :aria-pressed="activeTab === 'pending'" @click="activeTab = 'pending'">진행할 평가 <span>{{ pending.length }}</span></button><button :class="{ active: activeTab === 'completed' }" :aria-pressed="activeTab === 'completed'" @click="activeTab = 'completed'">완료한 평가 <span>{{ completed.length }}</span></button></div><p v-if="loading" class="muted" role="status">초대받은 평가를 불러오고 있습니다…</p><div v-else-if="!visible.length && !error" class="card empty-state"><span class="empty-symbol">{{ activeTab === 'pending' ? '↗' : '✓' }}</span><h2>{{ activeTab === 'pending' ? '진행할 평가가 없습니다' : '아직 완료한 평가가 없습니다' }}</h2><p class="muted">{{ activeTab === 'pending' ? '기업이 초대한 이메일과 같은 계정인지 확인해 주세요.' : '평가를 제출하면 이곳에서 완료 내역을 확인할 수 있습니다.' }}</p></div><div class="project-grid"><article v-for="item in visible" :key="item.invitation_id" class="card project-card"><div class="review-heading"><span class="badge" :class="tone(item.state)">{{ stateLabels[item.state] || item.state }}</span><span v-if="item.is_fixture" class="badge amber">기능 확인용 · 실제 평가 아님</span></div><h2>{{ item.title }}</h2><p class="muted">{{ item.scenario_title }}</p><div class="chips"><span class="badge">제한 시간 {{ duration(item.duration_seconds) }}</span><span class="badge">AI 동료와 협업</span><span class="badge">과제 문서 작성</span></div><div class="notice">{{ item.state === 'submitted' ? '과제가 제출되었습니다. 완료 내역을 확인할 수 있습니다.' : ['running','paused'].includes(item.state) ? '저장된 내용과 남은 시간으로 이어서 응시할 수 있습니다.' : item.state === 'expired' ? '초대가 만료되었습니다. 기업 담당자에게 문의해 주세요.' : '과제 안내와 오피스 사용법을 확인하세요. 시간은 응시 시작 이후부터 흐릅니다.' }}</div><div class="card-bottom"><span class="muted">{{ item.state === 'submitted' ? '응시가 완료되었습니다.' : '안내 확인 → 동의 → 응시 시작' }}</span><button class="primary" :disabled="item.state === 'expired' || !!opening" @click="open(item)">{{ opening === item.invitation_id ? '확인 중…' : item.state === 'submitted' ? '완료 내역' : ['paused','running'].includes(item.state) ? '이어서 응시 →' : '응시 준비하기 →' }}</button></div></article></div></main></template>
